// The Waffles icons as React components, generated from the SVGs in web/icons/ (standard and inverted;
// the brand icons were never copied). Same names, props and markup as the Waffles icon build
// (gulp + SVGR, replaced by this script): <CrossIcon size={12|18|24} color title aria-hidden className ref>.
// The SVG colour #3AC becomes the `color` prop (default currentColor).
// Output: web/src/waffles/react/icons/ (generated, do not edit by hand).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { transform } from "@svgr/core";
import svgo from "@svgr/plugin-svgo";
import jsx from "@svgr/plugin-jsx";

const web = fileURLToPath(new URL("../", import.meta.url));
const SRC = path.join(web, "icons"), OUT = path.join(web, "src/waffles/react/icons");
const svgoConfig = { plugins: [{ name: "preset-default", params: { overrides: { removeViewBox: false } } }, "removeTitle", "removeDimensions"] };
const pascal = (s) => s.replace(/(^|[-_])([a-z0-9])/g, (_, __, c) => c.toUpperCase());

const template = (variables, { tpl }) => tpl`
import * as React from 'react';

interface IconProps {
  'aria-hidden'?: boolean;
  className?: string;
  color?: string;
  size?: 12 | 18 | 24;
  title?: string;
  titleId?: string;
}
const ${variables.componentName} = React.forwardRef(
  (
    { 'aria-hidden': ariaHidden = false, className, color = 'currentColor', size = 18, title, titleId }: IconProps,
    ref: React.Ref<SVGSVGElement>,
  ) => ${variables.jsx},
);
export default ${variables.componentName};
`;

fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });
const index = [];
for (const [dir, suffix] of [["standard", ""], ["inverted", "Inverted"]]) {
  for (const file of fs.readdirSync(path.join(SRC, dir)).filter((f) => f.endsWith(".svg")).sort()) {
    const name = pascal(file.replace(/\.svg$/, "")) + suffix;
    const svg = fs.readFileSync(path.join(SRC, dir, file), "utf8");
    const code = await transform(svg, {
      plugins: [svgo, jsx],
      svgoConfig,
      typescript: true,
      titleProp: true,
      dimensions: false,
      expandProps: false,
      replaceAttrValues: { "#3AC": "{color}", "#33AACC": "{color}" },
      svgProps: { "aria-hidden": "{ariaHidden}", className: "{className}", height: "{size}", ref: "{ref}", role: "img", width: "{size}" },
      template,
    }, { componentName: name });
    if (/#3AC|#33AACC/i.test(code)) throw new Error(name + ": colour not replaced");
    fs.writeFileSync(path.join(OUT, name + ".tsx"), "// Generated by web/tools/build-icons.mjs from web/icons/" + dir + "/" + file + ". Do not edit by hand.\n" + code);
    index.push(`export { default as ${name}Icon } from './${name}';`);
  }
}
fs.writeFileSync(path.join(OUT, "index.ts"), "// Generated by web/tools/build-icons.mjs. Do not edit by hand.\n" + index.join("\n") + "\n");
console.log("icons:", index.length, "components →", path.relative(web, OUT));
